  const activeDrawingKey=()=>`optimum.cad.active.${state.companyId||'default'}`;
  const rememberActiveDrawing=()=>{if(eng.selectedDrawingId)localStorage.setItem(activeDrawingKey(),JSON.stringify({drawingId:eng.selectedDrawingId,revisionId:eng.selectedRevisionId}));};
