    if(eng.mode!=='editor'||!eng.selectedRevisionId||!eng.dirty)return false;
    const payload={version:1,companyId:state.companyId||null,drawingId:eng.selectedDrawingId,revisionId:eng.selectedRevisionId,baseLockVersion:eng.lockVersion,savedAt:new Date().toISOString(),snapshot:deepClone(eng.snapshot),settings:deepClone(eng.settings)};
