  async function load(){
    if(!state.companyId||!can('drawings.view')){Object.assign(eng,{drawings:[],revisions:[],boq:[],marks:[],markUpdates:[],catalog:[],assets:[],links:[],loadWarnings:[]});return;}
    const f=`eq.${state.companyId}`;
    // Keep the engineering register light. Revision snapshots can be very large,
    // so load only revision metadata here and fetch a single payload on demand.
    // The normalized BOQ table is not needed for editor rendering; takeoff is
    // calculated from the active snapshot. This avoids multi-megabyte company-wide
    // hydration every time the CAD route opens.
    eng.revisionPayloads.clear();
    const requests=[
      ['drawings',api.select('engineering_drawings',{select:'id,company_id,project_id,site_id,folder_id,source_document_id,drawing_no,title,discipline,drawing_type,status,current_revision_id,created_by,updated_by,created_at,updated_at,archived_at',filters:{company_id:f},order:'updated_at.desc',limit:600}),true],
      ['revisions',api.select('engineering_revisions',{select:'id,company_id,drawing_id,revision_number,revision_code,status,change_note,lock_version,created_by,created_at,updated_at,submitted_at,published_at',filters:{company_id:f},order:'revision_number.desc',limit:1800}),true],
      ['marks',api.select('engineering_review_marks',{select:'id,company_id,drawing_id,revision_id,x,y,title,body,status,priority,target_kind,target_id,assigned_to,due_at,created_by,created_at,updated_at,resolved_by,resolved_at',filters:{company_id:f},order:'created_at.desc',limit:1800}),false],
      ['markUpdates',api.select('engineering_review_mark_updates',{select:'id,company_id,mark_id,body,created_by,created_at',filters:{company_id:f},order:'created_at.asc',limit:3000}),false],
      ['catalog',api.select('engineering_catalog_items',{order:'sort_order.asc,code.asc',limit:1000}),false],
      ['assets',api.select('engineering_assets',{select:'id,company_id,drawing_id,revision_id,kind,original_filename,storage_bucket,storage_path,mime_type,size_bytes,state,uploaded_by,created_at,finalized_at',filters:{company_id:f},order:'created_at.desc',limit:1800}),false],
      ['links',api.select('engineering_document_links',{select:'id,company_id,drawing_id,revision_id,document_id,relation_type,created_by,created_at',filters:{company_id:f},order:'created_at.desc',limit:1800}),false]
    ];
    const settled=await Promise.allSettled(requests.map(([,promise])=>promise));
    const loaded={},warnings=[];
    settled.forEach((result,index)=>{const [key,,critical]=requests[index];if(result.status==='fulfilled')loaded[key]=result.value;else if(critical)throw result.reason;else{loaded[key]=[];warnings.push({key,message:String(result.reason?.message||result.reason||'Load failed')});}});
    Object.assign(eng,{...loaded,boq:[],loadWarnings:warnings});
    const drawings=eng.drawings;
    if(eng.selectedDrawingId&&!drawings.some((x)=>x.id===eng.selectedDrawingId)){eng.mode='register';eng.selectedDrawingId=null;eng.selectedRevisionId=null;clearActiveDrawing();}
    if(eng.mode==='register'&&!eng.selectedDrawingId){try{const saved=JSON.parse(localStorage.getItem(activeDrawingKey())||'null');if(saved?.drawingId&&drawings.some((x)=>x.id===saved.drawingId))await openDrawing(saved.drawingId,saved.revisionId||null);}catch{clearActiveDrawing();}}
  }
