  eng.snapshot.nodes.forEach((node,index)=>{const item=catalogItem(node.catalogCode),defaults=catalogDefaults(item),p=node.properties||(node.properties={});if(!node.label){node.label=`${item?.code||'NODE'}-${index+1}`;count++;}if(!p.networkLevel){p.networkLevel=defaults.network_level||(['main_cabinet','sub_cabinet','fdt'].includes(item?.symbol_key)?'main':'secondary');count++;}if(['termination_box','fat','odb'].includes(item?.symbol_key)&&!p.boxNo){p.boxNo=String(index+1).padStart(2,'0');count++;}const nx=Math.min(eng.settings.width-90,Math.max(90,node.x)),ny=Math.min(eng.settings.height-90,Math.max(90,node.y));if(nx!==node.x||ny!==node.y){node.x=nx;node.y=ny;count++;}});
