  if(!count){eng.history.pop();toast('info',L('لا توجد بيانات آمنة ناقصة يمكن إصلاحها تلقائيًا.','No safe missing data can be repaired automatically.'));return 0;}markDirty();render();toast('success',`${L('تم إصلاح','Repaired')} ${count} ${L('مشكلة بيانات بدون تغيير التصميم','data issues without changing the design')}`);return count;
