  const endPointer=()=>{if(eng.pan){eng.pan=null;viewport?.classList.remove('is-panning');return;}if(eng.marquee){const {start,current,additive}=eng.marquee,x1=Math.min(start.x,current.x),x2=Math.max(start.x,current.x),y1=Math.min(start.y,current.y),y2=Math.max(start.y,current.y);const picks=[];eng.snapshot.nodes.forEach((n)=>{if(n.x>=x1&&n.x<=x2&&n.y>=y1&&n.y<=y2)picks.push(selectionKey('node',n.id));});eng.snapshot.routes.forEach((r)=>{const m=routeMidpoint({...r,points:routeResolvedPoints(eng.snapshot,r)});if(m.x>=x1&&m.x<=x2&&m.y>=y1&&m.y<=y2)picks.push(selectionKey('route',r.id));});eng.snapshot.annotations.forEach((a)=>{if(a.x>=x1&&a.x<=x2&&a.y>=y1&&a.y<=y2)picks.push(selectionKey('text',a.id));});setSelection(additive?[...eng.selection,...picks]:picks);eng.marquee=null;svg.querySelector('[data-eng-marquee]')?.remove();render();return;}if(!eng.drag)return;const completedDrag=eng.drag,moved=completedDrag.moved,before=completedDrag.before;eng.drag=null;if(moved){eng.history.push(before);if(eng.history.length>80)eng.history.shift();eng.future=[];if(completedDrag.kind==='node')attachNodeToNearestRoute(nodeById(completedDrag.id),{threshold:42,silent:true});markDirty();}render();if(!moved&&completedDrag.kind==='routeLabel')setTimeout(()=>openRouteLabelEditor(routeById(completedDrag.id)),20);else if(!moved&&completedDrag.kind==='text')setTimeout(()=>openTextEditor(eng.snapshot.annotations.find((item)=>item.id===completedDrag.id)),20);};
