  function deleteSelected(){if((!eng.selected&&!eng.selection.length)||currentRevision()?.status!=='draft')return;const items=eng.selection.length?selectedObjects():[{kind:eng.selected.kind,id:eng.selected.id,obj:selectedObject()}];const nodeIds=new Set(items.filter((x)=>x.kind==='node').map((x)=>x.id)),routeIds=new Set(items.filter((x)=>x.kind==='route').map((x)=>x.id)),textIds=new Set(items.filter((x)=>x.kind==='text').map((x)=>x.id));const connected=eng.snapshot.routes.filter((x)=>nodeIds.has(x.sourceNodeId)||nodeIds.has(x.targetNodeId));if(connected.length&&!confirm(L(`سيتم حذف المحدد و${connected.length} مسار مرتبط. متابعة؟`,`Delete the selection and ${connected.length} connected route(s)?`)))return;pushHistory();eng.snapshot.nodes=eng.snapshot.nodes.filter((x)=>!nodeIds.has(x.id));eng.snapshot.routes=eng.snapshot.routes.filter((x)=>!routeIds.has(x.id)&&!nodeIds.has(x.sourceNodeId)&&!nodeIds.has(x.targetNodeId));eng.snapshot.annotations=eng.snapshot.annotations.filter((x)=>!textIds.has(x.id));setSelection([]);render();}
