  function keydown(ev){if(eng.mode!=='editor')return false;const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)&&ev.key!=='Escape')return false;const key=ev.key.toLowerCase();if(ev.key==='Escape'){ev.preventDefault();if(eng.pasteMode){stopPasteMode({silent:true});}else if(eng.routeDraft){if(eng.routeDraft.points.length>=2)finishActiveRoute();else{eng.routeDraft=null;render();}}else{eng.tool='select';eng.connectSourceId=null;render();}return true;}if(ev.key==='Enter'&&eng.routeDraft){ev.preventDefault();finishActiveRoute();return true;}if((ev.key==='Delete'||ev.key==='Backspace')&&(eng.selected||eng.selection.length)){ev.preventDefault();deleteSelected();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='a'){ev.preventDefault();setSelection([...eng.snapshot.nodes.map((x)=>selectionKey('node',x.id)),...eng.snapshot.routes.map((x)=>selectionKey('route',x.id)),...eng.snapshot.annotations.map((x)=>selectionKey('text',x.id))]);render();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='c'){ev.preventDefault();copySelection();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='x'){ev.preventDefault();if(copySelection({silent:true}))deleteSelected();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='v'){ev.preventDefault();startPasteMode();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='s'){ev.preventDefault();if(ev.shiftKey)save({force:true});else save({force:true,silent:true}).then(()=>openSaveToFilesDialog());return true;}if((ev.ctrlKey||ev.metaKey)&&key==='e'){ev.preventDefault();openExportMenu();return true;}if((ev.ctrlKey||ev.metaKey)&&key==='z'){ev.preventDefault();if(!isEditableRevision())return true;if(ev.shiftKey){if(eng.future.length){eng.history.push(JSON.stringify(eng.snapshot));restore(eng.future.pop());}}else if(eng.history.length){eng.future.push(JSON.stringify(eng.snapshot));restore(eng.history.pop());}return true;}if((ev.ctrlKey||ev.metaKey)&&ev.key==='0'){ev.preventDefault();fitCanvas();return true;}if(key==='v'){eng.tool='select';eng.pasteMode=false;render();return true;}if(key==='h'){eng.tool='pan';eng.pasteMode=false;render();return true;}if(key==='c'){eng.tool='connect';eng.connectSourceId=null;eng.pasteMode=false;render();return true;}if(key==='r'){eng.tool='route';eng.pasteMode=false;render();return true;}if(key==='f'){fitCanvas();return true;}if(key==='l'){ev.shiftKey?smartRouteLayout():autoLayout();return true;}if(key==='?'){openShortcuts();return true;}return false;}
  return {load,page,help,handleAction,handleChange,handleInput,handleSubmit,keydown,openDrawing,state:eng};
